update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-reims/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Reims et dans la Marne","mecanisme":"Dans la Marne, la production se joue sur des fenêtres courtes. Quelques semaines de vendanges, une campagne betteravière qui tourne sans coupure, des séries d''embouteillage calées au jour près. Nous préparons les équipements avant la fenêtre et nous tenons l''astreinte pendant. Nos techniciens se déplacent partout en France.","cta":"Demander une intervention à Reims","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, tenue pendant les campagnes comme le reste de l''année."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients en France, dont plus de 80 suivis en contrat régulier"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, évaluation transmise avant l''arrivée"},{"valeur":"24/24 et 7/7","libelle":"astreinte en option, la seule réponse tenable pendant une campagne"}]},{"type":"probleme","punchline":"Une campagne betteravière ne s''interrompt pas pour une maintenance. Elle tourne jusqu''au bout, et tout ce qui n''a pas été fait avant se paie pendant.","puces":[{"accroche":"La fenêtre de vendange ne se rattrape jamais.","texte":"Pressoirs et réception de vendange servent quelques semaines par an, et l''année entière en dépend."},{"accroche":"Le procédé sucrier tourne sans coupure.","texte":"Pendant la campagne, l''arrêt d''un organe se répercute sur toute la chaîne, jour et nuit."},{"accroche":"L''embouteillage vit au rythme des séries.","texte":"Changement de format, réglage, redémarrage : une remplisseuse capricieuse mange le planning de la semaine."},{"accroche":"L''emballage tourne vite et change souvent.","texte":"Cartonnerie et impression enchaînent les formats, et l''usure des entraînements avance avec."},{"accroche":"Le technicien expérimenté manque partout dans la Marne.","texte":"Les annonces restent ouvertes, et le préventif glisse d''un mois sur l''autre."}]}]'::jsonb) where path = '/implantations/maintenance-industrielle-reims/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Remise en état des équipements saisonniers avant la fenêtre","texte":"pressoirs, réception, convoyage, pompage."},"benefice":"Le matériel démarre la campagne prêt, au lieu d''être réparé en pleine saison."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 pendant les campagnes","texte":", circuit et priorités écrits à l''avance."},"benefice":"Un appel de nuit trouve un technicien mobilisé, pas un répondeur."},{"prestation":{"accroche":"Lignes d''embouteillage et de conditionnement suivies dans le détail","texte":"remplisseuse, bouchage, étiquetage, convoyage, froid."},"benefice":"Les changements de format cessent d''être le moment où tout se dérègle."},{"prestation":{"accroche":"Machines rapides d''emballage et d''impression","texte":"entraînements, transmissions, réglages, reprise d''usure."},"benefice":"La cadence se tient sans dégrader la qualité de façonnage."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure et tuyauterie](/expertises/soudure/)."},"benefice":"Une panne qui mélange les métiers reste un seul contrat et un seul interlocuteur."},{"prestation":{"accroche":"Arrêt technique préparé de J-90 à J-30","texte":", restitution à la demi-journée."},"benefice":"Le redémarrage tombe à la date prévue, pas deux jours après."}],"prose":[{"texte":"Pour les lignes alimentaires, voir la [maintenance en agroalimentaire](/secteurs/agroalimentaire/). Pour les entrepôts de l''axe autoroutier, voir la [maintenance des équipements logistiques](/secteurs/logistique/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"équipement, symptôme, criticité, fenêtre de production, accès au site."},{"titre":"Nous vous rappelons dans l''heure","texte":"qualification du besoin, du profil disponible et des pièces à prévoir."},{"titre":"Le devis précède le déplacement","texte":"périmètre, conditions, chiffrage écrit, options d''astreinte comprises."},{"titre":"L''intervention suit votre protocole","texte":"accueil sécurité, plan de prévention, consignation, diagnostic."},{"titre":"La cause racine est traitée après la remise en route","texte":"mesures, historique, conditions réelles d''exploitation."},{"titre":"Le compte rendu part dans votre GMAO","texte":"constat, actions, pièces, organes à reprendre avant la prochaine campagne."}]},{"type":"garanties","puces":[{"accroche":"Le préventif se cale sur votre calendrier, pas sur le nôtre","texte":"les opérations lourdes tombent hors fenêtre de production, et le programme s''écrit avec votre responsable maintenance."},{"accroche":"Vous savez qui entre sur le site","texte":"10 % des candidats retenus après entretien technique et comportemental, résultats d''évaluation présentés avant l''arrivée."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en option. Le reste se dit avant d''engager."}]},{"type":"cta","question":"Besoin de préparer vos équipements avant la prochaine campagne ?","bouton":"Demander une intervention à Reims","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-reims/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un technicien polyvalent intégré pour tenir un parc machines en forte cadence","texte":"papier et emballage, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Deux techniciens intégrés en 3x8 sur des lignes liquides et poudre","texte":"cadence continue, nutrition infantile","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"18 à 25 techniciens sur plusieurs sites du Grand Est depuis juin 2023","texte":"compétences apportées pour une transition industrielle","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"1 à 3 techniciens en renfort des équipes maintenance sur plusieurs sites de production, depuis octobre 2024","texte":"disponibilité machine tenue semaine après semaine","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"Un technicien intégré pendant l''arrêt estival pour tenir les équipements critiques","texte":"été 2025, équipe partiellement en congés","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Reims, alors que votre siège est à Lyon ?","reponse":"Oui. Nos techniciens se déplacent partout en France et interviennent sur site. Nos 4 agences sont Lyon (siège), Montréal, Dubaï et Madrid, et nous ne publions pas d''adresse rémoise que personne n''occupe. Votre demande est rappelée dans l''heure aux horaires ouvrés. Pendant une campagne, ce qui compte est l''astreinte contractuelle et le technicien qui décroche, pas la distance affichée sur une page."},{"question":"Quelles communes couvrez-vous dans la Marne ?","reponse":"Reims et son agglomération, Bezannes, Cormontreuil, Tinqueux, Saint-Brice-Courcelles, Witry-lès-Reims, puis Épernay et Châlons-en-Champagne. Au-delà, le relais se fait sur le Grand Est puis sur le réseau national."},{"question":"Pouvez-vous tenir une astreinte pendant toute une campagne ?","reponse":"Oui, c''est l''usage de l''option astreinte 24/24 et 7/7. Le circuit d''appel, les priorités et les équipements couverts s''écrivent avant le démarrage de la campagne, et le dimensionnement se décide avec vous."},{"question":"Intervenez-vous sur les lignes d''embouteillage et de conditionnement ?","reponse":"Oui : remplissage, bouchage, étiquetage, convoyage, froid et utilités associées. Les changements de format et les réglages font partie du périmètre quand ils entrent dans le contrat."},{"question":"Que faites-vous que notre prestataire actuel ne fait pas ?","reponse":"Nous mesurons et nous restituons : disponibilité par équipement, récurrence des défauts, respect du plan préventif. Un périmètre d''essai suffit à comparer, sans rien changer d''autre à votre organisation."},{"question":"Combien coûte un contrat de préventif ?","reponse":"L''abonnement [Zéro arrêt](/offres/zero-arret/) est chiffré sur devis, engagement type 6 mois renouvelable. Préventif planifié, priorité en cas de panne, astreinte en option, périmètre écrit équipement par équipement après un diagnostic gratuit."}]},{"type":"ctaFinal","question":"Besoin d''une astreinte qui décroche vraiment pendant votre saison ?","bouton":"Demander une intervention à Reims","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-reims/';
